package de.sebaro_ventures.design.designsystem

import android.os.Build
import android.view.HapticFeedbackConstants
import android.view.View
import androidx.compose.runtime.Composable
import androidx.compose.runtime.Stable
import androidx.compose.runtime.remember
import androidx.compose.ui.input.InputMode
import androidx.compose.ui.input.InputModeManager
import androidx.compose.ui.platform.LocalInputModeManager
import androidx.compose.ui.platform.LocalView

/**
 * Haptics of D48 on the phone; both follow the system's touch-feedback setting and play only while the screen is
 * operated by touch (D85): in keyboard input mode (hardware keyboard, D-pad, switch access) they stay silent.
 */
@Stable
class SbHaptics(
    private val view: View,
    private val inputModeManager: InputModeManager,
    private val enabled: Boolean = true,
) {
    // D105 (24): [enabled] = false is the app's own „Vibration“ switch, passed through the wrapper's haptics parameter
    private fun touch(): Boolean = enabled && inputModeManager.inputMode == InputMode.Touch

    /** The primary action succeeded: one short, light pulse. */
    fun success() {
        if (!touch()) return
        view.performHapticFeedback(
            if (Build.VERSION.SDK_INT >= 30) HapticFeedbackConstants.CONFIRM else HapticFeedbackConstants.CONTEXT_CLICK,
        )
    }

    /** A deletion was confirmed: the stronger double pulse. */
    fun deleteConfirmed() {
        if (!touch()) return
        view.performHapticFeedback(
            if (Build.VERSION.SDK_INT >= 30) HapticFeedbackConstants.REJECT else HapticFeedbackConstants.LONG_PRESS,
        )
    }
}

/** The haptics of this screen's view; [enabled] = false (the app's switch is off, D105 (24)) keeps both silent. */
@Composable
fun rememberSbHaptics(enabled: Boolean = true): SbHaptics {
    val view = LocalView.current
    val inputModeManager = LocalInputModeManager.current
    return remember(view, inputModeManager, enabled) { SbHaptics(view, inputModeManager, enabled) }
}
